for (c,dev),(rev,seats,st) in best.items():
    if st.strip()=='取消': continue
    need[c]=need.get(c,0)+seats
for c in ['P03-R','P09-R','L01-R','L02-R']:
    print(c,cat[c],prio[c],need[c])
